    CITATION_DOIS = [FEATURECOUNTS_CITATION_DOI]
    CITATION_URLS = [f"{DOI_URL}{FEATURECOUNTS_CITATION_DOI}"]
    CITATION_TEXT = FEATURECOUNTS_CITATION_TEXT
    VERSION = "2.1.1+galaxy1"
