        out = Path(output_dir) / cls.NODE_ID
        out.mkdir(parents=True, exist_ok=True)
        split_alignments_dir = out / "split_alignments"
        split_alignments_dir.mkdir(parents=True, exist_ok=True)
        return [split_alignments_dir]

