        cls._add_advanced_options(cmd, inputs)
        _add_if_value(cmd, "--cpu", max(1, int(inputs.get("threads", 1)) - 1))
        _add_if_value(cmd, "--seed", inputs.get("seed", 42))
        cmd.extend([str(inputs.get("seqfile", "")), str(inputs.get("seqdb", ""))])
