class HyPhyBStillNode(CommandNode):
    """Detect invariant or near-invariant codon sites with HyPhy B-STILL."""

    NODE_ID = "hyphy_b_still"
    DISPLAY_NAME = "HyPhy-B-STILL"
    REQUIRED_CONDA_PACKAGES = ["hyphy"]
    CATEGORY = "phylogeny"
